using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side implementation with direct data access.
/// Used when the app runs in Interactive Server mode.
/// </summary>
public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> Shipments =
    [
        new() { Id = 1, TrackingNumber = "TRK-1001", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics – 2 boxes" },
        new() { Id = 2, TrackingNumber = "TRK-1002", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.Pending, ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(4), CustomerEmail = "bob@example.com", Description = "Furniture – 1 pallet" },
        new() { Id = 3, TrackingNumber = "TRK-1003", Origin = "Seattle, WA", Destination = "Denver, CO", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "carol@example.com", Description = "Medical supplies" },
        new() { Id = 4, TrackingNumber = "TRK-1004", Origin = "Houston, TX", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-2), CustomerEmail = "dave@example.com", Description = "Auto parts – 3 crates" },
        new() { Id = 5, TrackingNumber = "TRK-1005", Origin = "Boston, MA", Destination = "Atlanta, GA", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "eve@example.com", Description = "Perishable goods – refrigerated" },
        new() { Id = 6, TrackingNumber = "TRK-1006", Origin = "San Francisco, CA", Destination = "Portland, OR", Status = ShipmentStatus.PickedUp, ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(1), CustomerEmail = "frank@example.com", Description = "Documents – express" },
    ];

    private static int _nextId = 7;

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (Shipments)
        {
            return Task.FromResult(Shipments.ToList());
        }
    }

    public Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        lock (Shipments)
        {
            var shipment = Shipments.FirstOrDefault(
                s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        lock (Shipments)
        {
            var shipment = Shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
            {
                shipment.Status = newStatus;
            }
        }
        return Task.CompletedTask;
    }
}

@page "/"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch Dashboard</PageTitle>

<h1>Dispatch Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination…"
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments…</em></p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>ETA</th>
                    <th>Description</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @StatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.ShippedDate.ToString("MMM dd")</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd")</td>
                        <td>@s.Description</td>
                        <td>
                            <select class="form-select form-select-sm"
                                    value="@s.Status"
                                    @onchange="e => UpdateStatus(s, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status" selected="@(status == s.Status)">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrEmpty(filterText) ||
                        s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase))
            .Where(s => string.IsNullOrEmpty(statusFilter) ||
                        s.Status.ToString() == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string StatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

